        throw new Error("wild_child_choice_invalid");
      this.events.push({
        timestamp: Date.now(),
        type: "wild_child_model_chosen",
        payload: { actorId: b.actorId, day: 1, targetId: call.args.target_id },
      });
      return true;
    } finally {
      closeWildChildChoice(b, status);
    }
  }
}

/**
 * 负责孤独少女首夜心仪对象选择及原失败／取消路径。
 * 输入为只读板子、原参与者与 provider；输出为心仪对象提交成功或准备中断。
 * 先核准备状态再打开原窗口，await 两侧复验参与者；阵营归属、库存及 finally 关闭归原生命周期。
 * 已失败或关闭的选择不重写游戏参数，不重新开启准备，也不授予过期请求许可。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { Phase, type World, type GameEvent, type ActionProvider } from "../../../../core/domain";
import { GameActionRequestFactory } from "../../../engine/action_request_factory";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import { LONELY_GIRL_POLICY, readLonelyGirlTool } from "./state";
import {
  lonelyGirlBinding,
  lonelyGirlReady,
  hasActiveLonelyGirl,
  openLonelyGirlChoice,
  validLonelyGirlChoice,
  commitLonelyGirlChoice,
  closeLonelyGirlChoice,
} from "./lifecycle";
export class LonelyGirlSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (hasActiveLonelyGirl(this.world)) throw new Error("lonely_girl_setup_reentry");
    if (lonelyGirlReady(this.world)) return true;
    const b = lonelyGirlBinding(this.world);
    if (!b || b.status !== "pending" || config !== b.config || day !== 1)
      throw new Error("lonely_girl_setup_unavailable");
    let status: "failed" | "cancelled" = "failed";
    try {
      if (!openLonelyGirlChoice(b, isCurrent)) {
        status = "cancelled";
        return false;
      }
      const request = new GameActionRequestFactory(this.world, this.events, day).create({
        phase: Phase.Night,
        actorId: b.actorId,
        allowedTools: ["choose_admired_player"],
        stage: "lonely_girl",
        requiresAction: true,
        summary: { key: "turn.lonely_girl.required" },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      if (!validLonelyGirlChoice(b)) {
        status = "cancelled";
        return false;
      }
      const raw = await provider.getAction(request);
      if (!validLonelyGirlChoice(b)) {
        status = "cancelled";
        return false;
      }
      const call = readLonelyGirlTool(raw);
      if (!call) throw new Error("lonely_girl_required_choice_missing");
      const result = this.gateway.validateAndSanitize(this.world, b.actorId, call, {
        phase: Phase.Night,
        day,
        lonelyGirlScope: b,
      });
      if (!validLonelyGirlChoice(b)) {
        status = "cancelled";
        return false;
      }
      if (!result.ok) throw new Error("lonely_girl_choice_invalid");
      const camp = commitLonelyGirlChoice(b, call.args.target_id);
      if (!camp) throw new Error("lonely_girl_choice_invalid");
      this.events.push({
        timestamp: Date.now(),
        type: "lonely_girl_admired_chosen",
        payload: {
          policy: LONELY_GIRL_POLICY,
          actorId: b.actorId,
          day: 1,
          targetId: call.args.target_id,
          camp,
        },
      });
      return true;
    } finally {
      closeLonelyGirlChoice(b, status);
    }
  }
}

/**
 * 负责通过原婚礼 authority 顺序收集鬼魂新娘的新郎／见证人选择。
 * 输入为只读板子政策、当前阵容和引擎请求；输出为设置事实或中断结果，回合由原 owner 关闭。
 * 此协调器不改规则或绕过身份、失败及期限校验，每次请求保留原 factory 和 opaque turn。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { safeRecordLogicOp } from "../../../../recording/session_recorder";
import { GHOST_BRIDE_POLICY, readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import {
  Phase,
  type World,
  type GameEvent,
  type ActionProvider,
  type ActionStage,
  type ToolName,
} from "../../../../core/domain";
import { GameActionRequestFactory } from "../../../engine/action_request_factory";
import type { ToolGateway } from "../../../gateway/tool_gateway";
import {
  beginWeddingSetup,
  openWeddingTurn,
  closeWeddingTurn,
  closeWeddingSetup,
  ghostBrideReady,
  weddingSetup,
  weddingPair,
  weddingGroup,
  weddingActorView,
  weddingNightCapture,
  authorizedWeddingTurn,
  commitWeddingTool,
  takeWeddingChat,
} from "./authority";
/** 每次调用使用真实引擎工厂及 opaque 原回合，不启用 fallback。 */
export async function executeWeddingTurn(input: {
  world: World;
  gateway: ToolGateway;
  events: GameEvent[];
  provider: ActionProvider;
  day: number;
  actorId: number;
  kind: "bridegroom" | "chat" | "witness" | "knife";
  tool: ToolName;
  stage: ActionStage;
  isCurrent: () => boolean;
}): Promise<void> {
  const { world, gateway, events, provider, day, actorId, kind, tool, stage, isCurrent } = input;
  const scope = openWeddingTurn(world, kind, actorId, day, isCurrent);
  try {
    const view = weddingActorView(world, actorId);
    const request = new GameActionRequestFactory(world, events, day).create({
      phase: Phase.Night,
      actorId,
      allowedTools: [tool],
      stage,
      requiresAction: true,
      summary: { key: "request.summary.night_action" },
      context: {
        allow_fallback: false,
        action_failure_policy: "error",
        ...(kind === "witness" && view && "proposedWitnessId" in view
          ? { proposedWitnessId: view.proposedWitnessId }
          : {}),
      },
    });
    const raw = await provider.getAction(request);
    if (!authorizedWeddingTurn(world, actorId, Phase.Night, day, scope))
      throw new Error("ghost_bride_turn_revoked");
    const call = readWeddingTool(raw);
    if (!call || call.name !== tool) throw new Error("ghost_bride_required_action_missing");
    const valid = gateway.validateAndSanitize(world, actorId, call, {
      phase: Phase.Night,
      day,
      ghostBrideScope: scope,
      deferOperation: true,
    });
    if (!valid.ok || !valid.sanitizedCall) throw new Error("ghost_bride_action_invalid");
    const committed = commitWeddingTool(scope, call);
    const pair = weddingPair(world);
    if (!pair) throw new Error("ghost_bride_pair_unavailable");
    if (kind === "bridegroom" && committed)
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_pair_chosen",
        payload: { ...pair },
        audience: Object.freeze([pair.brideId, pair.groomId].sort((a, b) => a - b)),
      });
    if (kind === "witness" && call.name === "choose_wedding_witness") {
      const votes = weddingSetup(world)!.witnessVotes;
      if (votes.some((v) => v.actorId === actorId && v.targetId === call.args.target_id))
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_witness_vote",
          payload: {
            policy: GHOST_BRIDE_POLICY,
            groupId: pair.groupId,
            day: 1,
            actorId,
            targetId: call.args.target_id,
            voteIndex: votes.length as 1 | 2,
          },
          audience: Object.freeze([]),
        });
      const group = weddingGroup(world);
      if (committed && group)
        events.push({
          timestamp: Date.now(),
          type: "ghost_bride_group_chosen",
          payload: { ...group },
          audience: Object.freeze(
            [group.brideId, group.groomId, group.witnessId].sort((a, b) => a - b),
          ),
        });
    }
    if (
      kind === "knife" &&
      committed &&
      (call.name === "kill_vote" || call.name === "wedding_kill_vote")
    ) {
      const capture = weddingNightCapture(world, day)!;
      if (capture.owner === "none") throw new Error("ghost_bride_knife_owner_invalid");
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_knife_vote",
        payload: {
          policy: GHOST_BRIDE_POLICY,
          groupId: pair.groupId,
          day,
          owner: capture.owner,
          actorId,
          targetId: call.args.target_id,
          abstain: call.args.abstain,
        },
        audience: Object.freeze(capture.owner === "ordinary_pack" ? [] : [actorId]),
      });
      if (capture.owner === "ordinary_pack")
        events.push({
          timestamp: Date.now(),
          type: "wolf_kill_vote_cast",
          payload: { actorId, targetId: call.args.target_id, abstain: call.args.abstain },
          audience: Object.freeze([...capture.actorIds].sort((a, b) => a - b)),
        });
    }
    const actualDisagreement =
      kind === "witness" &&
      call.name === "choose_wedding_witness" &&
      weddingSetup(world)!.witnessVotes.some(
        (v) => v.actorId === actorId && v.targetId === call.args.target_id,
      );
    const recordCommit = () =>
      safeRecordLogicOp({
        scope: "gateway",
        op: "validate_tool_call",
        actorId,
        phase: Phase.Night,
        status: "ok",
        input: { tool: call.name, args: call.args },
      });
    if (kind !== "chat" && (committed || actualDisagreement)) recordCommit();
    if (!committed) throw new Error("ghost_bride_action_commit_failed");
    if (kind === "chat") {
      const message = takeWeddingChat(scope);
      if (!message) throw new Error("ghost_bride_chat_delivery_revoked");
      recordCommit();
      events.push({
        timestamp: Date.now(),
        type: "ghost_bride_partner_chat",
        payload: { policy: GHOST_BRIDE_POLICY, groupId: pair.groupId, ...message },
        audience: Object.freeze([message.actorId, message.recipientId].sort((a, b) => a - b)),
      });
    }
  } finally {
    closeWeddingTurn(scope);
  }
}
export class GhostBrideSetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (ghostBrideReady(this.world)) return true;
    const setup = weddingSetup(this.world);
    if (!setup || setup.status !== "pending" || day !== 1)
      throw new Error("ghost_bride_setup_unavailable");
    try {
      beginWeddingSetup(this.world, config, isCurrent);
      const base = {
        world: this.world,
        gateway: this.gateway,
        events: this.events,
        provider,
        day,
        isCurrent,
      };
      await executeWeddingTurn({
        ...base,
        actorId: setup.actorId,
        kind: "bridegroom",
        tool: "choose_bridegroom",
        stage: "ghost_bride_groom",
      });
      const pair = weddingPair(this.world)!;
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "chat",
          tool: "speak_to_partner",
          stage: "ghost_bride_chat",
        });
      for (const actorId of [pair.brideId, pair.groomId])
        await executeWeddingTurn({
          ...base,
          actorId,
          kind: "witness",
          tool: "choose_wedding_witness",
          stage: "ghost_bride_witness",
        });
      if (!isCurrent() || !ghostBrideReady(this.world))
        throw new Error("ghost_bride_setup_revoked");
      return true;
    } finally {
      closeWeddingSetup(this.world, isCurrent() ? "failed" : "cancelled");
    }
  }
}

/**
 * 负责首夜开局设置的确定序列：盗贼／千面人、野孩子、孤独少女、鬼魂新娘。
 * 输入为现场读取 World、网关、事件和板子的查询，以及原 provider、日期和唯一当前性回调；
 * 输出为全部准备通过，或在首个未准备完成／失效步骤之后立即返回 false。异常原样向上抛出。
 * 组合只装配原窗口并串行 await；选择、库存、接受权限和 finally 关闭仍由各机制拥有。
 * 不缓存 World 或提前读取构造参数；成功末尾没有额外当前性查询，也不推进阶段或生成快照。
 */
import type { GameEvent, ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import type { ActionProvider } from "../core/domain/actions";
import type { World } from "../core/domain/world";
import type { ToolGateway } from "../game/gateway/tool_gateway";
import {
  InitialIdentitySetupWindow,
  initialIdentitySetupReady,
  initialIdentityKind,
} from "../game/mechanisms/roles/initial_identity/ports";
import { WildChildSetupWindow, wildChildReady } from "../game/mechanisms/roles/wild_child/ports";
import { LonelyGirlSetupWindow, lonelyGirlReady } from "../game/mechanisms/roles/lonely_girl/ports";
import { GhostBrideSetupWindow, ghostBrideReady } from "../game/mechanisms/roles/ghost_bride/ports";

/** 查询只读取原调用点；事件数组与板子引用交给窗口，不产生新授权或状态镜像。 */
export interface GameSetupRuntime {
  world(): World;
  toolGateway(): ToolGateway;
  events(): GameEvent[];
  config(): ReadonlyBoardConfig;
}

export async function prepareGameSetup(
  runtime: GameSetupRuntime,
  actionProvider: ActionProvider,
  nightDay: number,
  nightIsCurrent: () => boolean,
): Promise<boolean> {
  // 每个 new 先查找原类，再按原顺序读取参数；execute 仍使用该实例作为 receiver。
  if (!initialIdentitySetupReady(runtime.world())) {
    const ready = await new InitialIdentitySetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
      initialIdentityKind(runtime.world())!,
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!wildChildReady(runtime.world())) {
    const ready = await new WildChildSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!lonelyGirlReady(runtime.world())) {
    const ready = await new LonelyGirlSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  if (!ghostBrideReady(runtime.world())) {
    const ready = await new GhostBrideSetupWindow(
      runtime.world(),
      runtime.toolGateway(),
      runtime.events(),
    ).execute(runtime.config(), actionProvider, nightDay, nightIsCurrent);
    if (!ready || !nightIsCurrent()) return false;
  }
  return true;
}

/**
 * 单元测试验证开局组合的现场读取、构造失败前缀及 await 后取消短路。
 * 输入为真实空 World、真实盗贼牌库／野孩子绑定和手写抛错查询；输出依据字面轨迹与原状态。
 * 机制执行及 finally 关闭使用原 owner，不运行整局或模型，不用待测函数生成预期或模拟许可。
 */
import { expect, test } from "bun:test";
import { Role, type GameEvent } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../src/core/domain/world";
import { ToolGateway } from "../../../src/game/gateway/tool_gateway";
import { prepareGameSetup, type GameSetupRuntime } from "../../../src/rulesets/game-setup";
import {
  installInitialIdentityDeal,
  initialIdentitySetupReady,
} from "../../../src/game/mechanisms/roles/initial_identity/deal";
import { bootstrapGame } from "../../../src/app/bootstrap";
import {
  wildChildBinding,
  hasActiveWildChild,
} from "../../../src/game/mechanisms/roles/wild_child/lifecycle";
import { foxBoard } from "../../support/features/cursed-fox/builders/scenario";

function unreadRuntime(world: World, trace: string[]): GameSetupRuntime {
  return {
    world() {
      trace.push("world");
      return world;
    },
    toolGateway() {
      trace.push("gateway");
      throw new Error("unexpected_gateway");
    },
    events() {
      trace.push("events");
      throw new Error("unexpected_events");
    },
    config() {
      trace.push("config");
      throw new Error("unexpected_config");
    },
  };
}

test("ready setup checks four live Worlds and does not call current at the successful tail", async () => {
  const trace: string[] = [];
  const ready = await prepareGameSetup(
    unreadRuntime(new World(), trace),
    {
      async getAction() {
        throw new Error("unexpected_provider");
      },
    },
    1,
    () => {
      trace.push("current");
      return false;
    },
  );
  expect(ready).toBe(true);
  expect(trace).toEqual(["world", "world", "world", "world"]);
});

test("an initial constructor argument failure preserves only the earlier reads and pending deal", async () => {
  const world = new World(),
    trace: string[] = [],
    failure = new Error("original_gateway_failure");
  installInitialIdentityDeal(world, [Role.Villager, Role.Villager], []);
  const runtime = unreadRuntime(world, trace);
  runtime.toolGateway = () => {
    trace.push("gateway");
    throw failure;
  };
  await expect(
    prepareGameSetup(
      runtime,
      {
        async getAction() {
          throw new Error("unexpected_provider");
        },
      },
      1,
      () => {
        trace.push("current");
        return true;
      },
    ),
  ).rejects.toBe(failure);
  expect(trace).toEqual(["world", "world", "gateway"]);
  expect(initialIdentitySetupReady(world)).toBe(false);
});

test("a real Wild Child cancellation stops after its own current check and preserves lifecycle closure", async () => {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter];
  const config = foxBoard(roles),
    game = bootstrapGame(config, { fixedRoles: roles });
  const trace: string[] = [],
    events: GameEvent[] = [],
    gateway = new ToolGateway();
  let active = true;
  const ready = await prepareGameSetup(
    {
      world() {
        trace.push("world");
        return game.world;
      },
      toolGateway() {
        trace.push("gateway");
        return gateway;
      },
      events() {
        trace.push("events");
        return events;
      },
      config() {
        trace.push("config");
        return game.boardConfig;
      },
    },
    {
      async getAction() {
        trace.push("provider");
        active = false;
        return { name: "choose_wild_model", args: { target_id: 2 } };
      },
    },
    1,
    () => {
      trace.push("current");
      return active;
    },
  );
  expect(ready).toBe(false);
  // 原请求绑定也会复验当前性；取消后的窗口复验只读一次，组合的 OR 不再调用它。
  expect(trace).toEqual([
    "world",
    "world",
    "world",
    "gateway",
    "events",
    "config",
    "current",
    "current",
    "current",
    "provider",
    "current",
  ]);
  expect(wildChildBinding(game.world)?.setup).toBe("cancelled");
  expect(hasActiveWildChild(game.world)).toBe(false);
  expect(events).toEqual([]);
});
